def suma(*tupla):
    total = 0
    for i in tupla:
        total = total + i
    return total

print(suma(5, 7, 9))

def opera(a, b):
    return (a + b, a - b, a * b, a / b)

s, r, m, d = opera(5, 10)
print(r, d)

def factorial(numero):
    return numero * factorial(numero - 1) if numero > 0 else 1

print(factorial(4))

